const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper function to create a cloud mask for Landsat Collection 2 data.
function maskL457sr(image) {
  // Bit 0 is fill, bit 1 is dilated cloud, bit 2 is cirrus, bit 3 is cloud, bit 4 is cloud shadow.
  const qa = image.select('QA_PIXEL');
  const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4)); // Cloud and cloud shadow
  // Apply the mask and scale the optical bands.
  const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true)
              .updateMask(cloud.not());
}

// Helper function for Landsat 8
function maskL8sr(image) {
  // Bit 3 is cloud, bit 4 is cloud shadow.
  const qa = image.select('QA_PIXEL');
  const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4)); // Cloud and cloud shadow
  // Apply the mask and scale the optical bands.
  const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true)
              .updateMask(cloud.not());
}

// Function to calculate NDBI
function calculateNDBI(image, swirBand, nirBand) {
  return image.normalizedDifference([swirBand, nirBand]).rename('NDBI');
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([39.6146, 24.4686]).buffer(15000); // Medina, Saudi Arabia, 15km buffer
  const date_1984 = ee.DateRange('1984-06-01', '1984-07-31'); // Widened for data availability
  const date_2018 = ee.DateRange('2018-07-01', '2018-07-31');

  // 2. Data Acquisition & Check
  const col_1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(date_1984);

  const col_2018 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(date_2018);

  const count_1984 = col_1984.size().getInfo();
  const count_2018 = col_2018.size().getInfo();

  if (count_1984 === 0 || count_2018 === 0) {
    console.log(`Image count 1984: ${count_1984}`);
    console.log(`Image count 2018: ${count_2018}`);
    console.log('C1: Empty Collection');
    return;
  }

  // 3. Processing
  const image_1984 = col_1984.map(maskL457sr).median().clip(aoi);
  const image_2018 = col_2018.map(maskL8sr).median().clip(aoi);

  // Rename bands for NDBI calculation
  const l5_bands = { swir: 'SR_B5', nir: 'SR_B4' };
  const l8_bands = { swir: 'SR_B6', nir: 'SR_B5' };

  const ndbi_1984 = calculateNDBI(image_1984, l5_bands.swir, l5_bands.nir);
  const ndbi_2018 = calculateNDBI(image_2018, l8_bands.swir, l8_bands.nir);

  // A threshold of 0 is typically used for NDBI to distinguish urban from non-urban.
  const urban_1984 = ndbi_1984.gt(0);
  const urban_2018 = ndbi_2018.gt(0);

  const scale = 1000;

  // 4. Calculation
  const urbanArea_1984 = urban_1984.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const urbanArea_2018 = urban_2018.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const area_1984 = ee.Number(urbanArea_1984.get('NDBI')).divide(1e6).getInfo(); // Convert to sq km
  const area_2018 = ee.Number(urbanArea_2018.get('NDBI')).divide(1e6).getInfo(); // Convert to sq km

  // 5. Validation & Final Answer
  if (area_1984 === null || area_2018 === null || isNaN(area_1984) || isNaN(area_2018)) {
    console.log(`1984 Urban Area (sq km): ${area_1984}`);
    console.log(`2018 Urban Area (sq km): ${area_2018}`);
    console.log('C3: Calculation Failure');
    return;
  }

  if (area_1984 === 0 || area_2018 === 0) {
      console.log(`1984 Urban Area (sq km): ${area_1984.toFixed(2)}`);
      console.log(`2018 Urban Area (sq km): ${area_2018.toFixed(2)}`);
      console.log('C2: No Valid Pixels');
      return;
  }

  console.log(`Initial image count 1984: ${count_1984}`);
  console.log(`Initial image count 2018: ${count_2018}`);
  console.log(`Estimated urban area in 1984 (sq km): ${area_1984.toFixed(2)}`);
  console.log(`Estimated urban area in 2018 (sq km): ${area_2018.toFixed(2)}`);

  if (area_2018 > area_1984) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
